def seed_performance_domains(apps, schema_editor):
    PMPDomain = apps.get_model("pmp_assessment", "PMPDomain")
    PMPQuestion = apps.get_model("pmp_assessment", "PMPQuestion")
    for name in PERFORMANCE_DOMAINS:
        PMPDomain.objects.get_or_create(name=name)
    for question in PMPQuestion.objects.select_related("topic", "domain"):
        topic_name = question.topic.name if question.topic_id else ""
        current_domain_name = question.domain.name if question.domain_id else ""
        domain = current_domain_name if current_domain_name in PERFORMANCE_DOMAINS else TOPIC_DOMAIN_MAP.get(topic_name, "")
        if not domain:
            text = f"{question.question_text} {question.task} {topic_name} {current_domain_name}".lower()
            matches = [name for name, words in KEYWORD_DOMAIN_MAP.items() if any(word in text for word in words)]
            domain = matches[0] if len(matches) == 1 else ""
        question.eco_domain = question.domain.name if question.domain_id else ""
        question.eco_task = question.task or topic_name
        if domain:
            question.performance_domain = domain
            question.import_status = "ready"
        else:
            question.import_status = "needs_domain_mapping"
            question.is_active = False
        question.save(update_fields=["performance_domain", "eco_domain", "eco_task", "import_status", "is_active", "updated_at"])

